// @ts-expect-error generated by `opennextjs-cloudflare build`
import openNext from "../.open-next/worker.js";
// @ts-expect-error generated by `opennextjs-cloudflare build`
import { runWithCloudflareRequestContext } from "../.open-next/cloudflare/init.js";
import { routeVoice } from "../src/lib/voice/server/route";
import { runWatchTick } from "../src/lib/watch/tick";
import { runNightlyReviews } from "../src/lib/strategist";

export { UserDO } from "./user-do";
export { CaseDO } from "./case-do";
export { VoiceDO } from "./voice-do";
export { PrepareFallback, LetterPipeline, NightlyWatch } from "./workflows";

type WorkflowBinding = { create(opts?: { id?: string; params?: unknown }): Promise<{ id: string }> };
const WATCH_CRON = "*/2 * * * *";
const NIGHTLY_CRON = "0 2 * * *";

type RunWithContext = (req: Request, env: unknown, ctx: unknown, fn: () => Promise<unknown>) => Promise<unknown>;
/**
 * Outside a request there is no OpenNext context, and getEnv() / the case client read it. OpenNext exposes the context
 * as a read-only getter over AsyncLocalStorage, so scheduled work runs inside its own request-context helper.
 */
function withContext(env: unknown, ctx: unknown, fn: () => Promise<unknown>): Promise<unknown> {
  const url = String((env as { APP_URL?: string }).APP_URL || "https://dossierly.cosmiclan.com");
  return (runWithCloudflareRequestContext as RunWithContext)(new Request(`${url}/__scheduled`), env, ctx, fn);
}
type Bindings = { NIGHTLY_WATCH?: WorkflowBinding };

export default {
  /** Voice WebSockets (browser + Twilio) go straight to VoiceDO; everything else is the Next app. */
  async fetch(req: Request, env: Record<string, unknown>, ctx: unknown): Promise<Response> {
    const voice = await routeVoice(req, env as never);
    return voice ?? (openNext.fetch as (r: Request, e: unknown, c: unknown) => Promise<Response>)(req, env, ctx);
  },

  /** Every 2 minutes: the per-user inbox watcher. Daily at 02:00 UTC: start one NightlyWatch instance per day (id is duplicate-safe). */
  async scheduled(controller: { scheduledTime: number; cron?: string }, env: Bindings, ctx: { waitUntil(p: Promise<unknown>): void }): Promise<void> {
    if (controller.cron === WATCH_CRON) {
      ctx.waitUntil(withContext(env, ctx, () => runWatchTick(env as never)).then(() => undefined, () => undefined));
      return;
    }
    if (controller.cron === NIGHTLY_CRON) {
      // Muse Wonder reviews every case that changed in the last 24 h.
      ctx.waitUntil(withContext(env, ctx, () => runNightlyReviews(env as never)).then(() => undefined, () => undefined));
    }
    const day = new Date(controller.scheduledTime).toISOString().slice(0, 10);
    try {
      await env.NIGHTLY_WATCH?.create({ id: `nightly-${day}`, params: { day } });
    } catch {
      // An instance for this day already exists (cron fired twice); nothing to do.
    }
  },
};
